[ExtensionOf(formControlStr(AVAEDINewCustAddress,Ok))]
internal final class AVAEDINewCustAddress_OK_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void clicked()
{
    FormRun   formRun = this.formRun();
    CustTable custTable = formRun.args().record();
    next clicked();

    AVAEDIAddress           newEDIAddress;

    select firstonly newEDIAddress
        where newEDIAddress.Num == custTable.AccountNum
           && newEDIAddress.RefRecId == custTable.RecId
           && newEDIAddress.RefTableId == CustTable.TableId
           && newEDIAddress.NameExt    == formRun.design().controlName('AVAEDIAddress_NameExt').valueStr()
           && newEDIAddress.Address    == formRun.design().controlName('AVAEDIAddress_Address').valueStr()
           && newEDIAddress.GLN        == formRun.design().controlName('AVAEDIAddress_GLN').valueStr();

    if (newEDIAddress.RecId)
    {
        newEDIAddress.selectForUpdate(true);
        newEDIAddress.NDXLogisticsLocationName1 = formRun.design().controlName('NDXEDIName1').valueStr();
        newEDIAddress.NDXLogisticsLocationName2 = formRun.design().controlName('NDXEDIName2').valueStr();
        newEDIAddress.NDXLogisticsLocationName3 = formRun.design().controlName('NDXEDIName3').valueStr();

        ttsbegin;
        newEDIAddress.doUpdate();
        ttscommit;
    }



}
